package hu.synostream.android;
import org.junit.Test;import static org.junit.Assert.*;
public class ConnectionModeTest {
 @Test public void successfulRouteDeterminesMode(){assertEquals(ConnectionMode.LOCAL,ConnectionMode.of(true,false,"Helyi kapcsolat"));assertEquals(ConnectionMode.DIRECT,ConnectionMode.of(true,false,"Közvetlen kapcsolat"));assertEquals(ConnectionMode.QUICKCONNECT,ConnectionMode.of(true,false,"QuickConnect"));assertEquals(ConnectionMode.LOCAL,ConnectionMode.of(true,false,"Local connection"));assertEquals(ConnectionMode.DIRECT,ConnectionMode.of(true,false,"Direct connection"));}
 @Test public void disconnectedAndDemoNeverClaimAnAuthenticatedRoute(){assertEquals(ConnectionMode.DISCONNECTED,ConnectionMode.of(false,false,"QuickConnect"));assertEquals(ConnectionMode.DEMO,ConnectionMode.of(false,true,null));assertEquals(ConnectionMode.DEMO,ConnectionMode.of(true,true,"Közvetlen kapcsolat"));}
 @Test public void unknownRouteIsNotDisplayedAsAnAddress(){for(String value:new String[]{null,"","fixture-host","https://example.invalid:1234"})assertEquals(ConnectionMode.UNKNOWN,ConnectionMode.of(true,false,value));}
 @Test public void bareIpDefaultsToHttpsWithoutAnExplicitPort(){assertEquals("https://192.168.1.10",NasClient.normalizeAddress("192.168.1.10"));assertEquals(-1,java.net.URI.create(NasClient.normalizeAddress("192.168.1.10")).getPort());assertEquals("https://192.168.1.10:5001",NasClient.normalizeAddress("https://192.168.1.10:5001/"));assertEquals("http://192.168.1.10:5000",NasClient.normalizeAddress("http://192.168.1.10:5000"));}
 @Test public void windowsSharePathsAreNotWebAddresses(){for(String value:new String[]{"\\\\192.168.1.10\\","\\\\192.168.1.10\\video"}){try{NasClient.normalizeAddress(value);fail("A file-sharing address must be rejected");}catch(IllegalArgumentException expected){}}}
 @Test public void quickConnectIdWithReachableLocalOverrideReportsLocal()throws Exception{NasClientTest fixture=new NasClientTest();fixture.start();try{NasClient client=new NasClient(new NasClient.Credentials("fixture-quickconnect","http://127.0.0.1:"+fixture.server.getLocalPort(),"test","secret",""));try{client.connect();assertEquals("Helyi kapcsolat",client.route);assertEquals(ConnectionMode.LOCAL,ConnectionMode.of(true,false,client.route));}finally{client.logout();}}finally{fixture.stop();}}
}
